// static
bool StructTraits<::local_ai::mojom::OrtModelFiles::DataView, ::local_ai::mojom::OrtModelFilesPtr>::Read(
    ::local_ai::mojom::OrtModelFiles::DataView input,
    ::local_ai::mojom::OrtModelFilesPtr* output) {
  bool success = true;
  ::local_ai::mojom::OrtModelFilesPtr result(::local_ai::mojom::OrtModelFiles::New());
  
      if (success && !input.ReadEncoder(&result->encoder))
        success = false;
      if (success && !input.ReadEncoderData(&result->encoder_data))
        success = false;
      if (success && !input.ReadDecoder(&result->decoder))
        success = false;
      if (success && !input.ReadDecoderData(&result->decoder_data))
        success = false;
      if (success && !input.ReadTokens(&result->tokens))
        success = false;
      if (success && !input.ReadMelFilters(&result->mel_filters))
        success = false;
  *output = std::move(result);
  return success;
}

