void SpeechRecognitionFactoryAsyncWaiter::Init(
    OrtModelFilesPtr files, bool* out_success) {
  base::RunLoop loop;
  proxy_->Init(
      std::move(files),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

